// Some portions generated by Claude
/**
 * Labels for the IRIs the Filters panel lists as values (repository-facets.ts). They have their own loader and caches
 * rather than the canvas's RdfExplorer: thousands of value IRIs would push the canvas's labels out of its small
 * persistent cache and re-label the whole graph after every batch. Labels the canvas already knows are used as they
 * are; the others are asked for in batches, values the panel shows first, one request at a time, after the explorer's
 * own queries. Found labels are kept six hours (in memory and IndexedDB), checked IRIs without a label ten minutes.
 * They are asked for with the canvas's label predicates (`lookupProperties`: RdfExplorer.labelProperties, which grow as
 * the explorer learns label predicates) and chosen as the canvas chooses them (`properties`: the preferred order).
 */
import type { FacetBackend } from "./facet-store-persistence.ts";
import { isQueryableResource, isSparqlTerm, sparqlNodeId, type SparqlTerm } from "./rdf-terms.ts";
import {
  chooseLabel,
  DEFAULT_LABEL_PROPERTIES,
  valueLabelQuery,
  type GraphScope,
  type LabelCandidate,
} from "./rdf-vocabulary.ts";

const LABEL_TTL_MS = 6 * 60 * 60 * 1000;
const NO_LABEL_TTL_MS = 10 * 60 * 1000;
const ROW_LIMIT = 4096;
const DEFAULT_BATCH = 64;
const DEFAULT_BUDGET = 20_000;
const TIMEOUT_MS = 30_000;

export type StoredLabel = { label: string | null };
type Binding = Record<string, SparqlTerm | undefined>;
type Rank = 0 | 1;

export class FacetValueLabels {
  version = 0;
  private readonly options: {
    execute: (query: string, signal: AbortSignal) => Promise<{ results?: { bindings?: Binding[] } }>;
    scope: GraphScope;
    namespace: string;
    languages: string[];
    /** The preferred label predicates, in order: they choose among a value's labels. */
    properties?: readonly string[];
    /** Every label predicate to ask for; the preferred ones are asked for too. */
    lookupProperties?: readonly string[];
    backend?: FacetBackend<StoredLabel>;
    now?: () => number;
    foreground?: { idle(): Promise<void> };
    known?: (iri: string) => string | undefined;
    batchSize?: number;
    budget?: number;
  };
  private labels = new Map<string, { label: string | null; expires: number }>();
  private queued = new Map<string, Rank>();
  private lookups = new Set<string>();
  private running = false;
  private batchSize: number;
  private asked = 0;
  private disposed = false;
  private generation = 0;
  private controller = new AbortController();
  private listeners = new Set<() => void>();

  constructor(options: FacetValueLabels["options"]) {
    this.options = options;
    this.batchSize = options.batchSize ?? DEFAULT_BATCH;
  }

  private now() {
    return (this.options.now ?? Date.now)();
  }

  /** The value's label, when one is known; the panel shows a readable form of the IRI meanwhile. */
  label(iri: string): string | undefined {
    const known = this.options.known?.(iri);
    if (known) return known;
    const cached = this.labels.get(iri);
    return cached && cached.expires > this.now() ? cached.label ?? undefined : undefined;
  }

  /** Values the panel shows ("shown") are labelled before the others ("background", at most 20,000 a session). */
  want(iris: readonly string[], priority: "shown" | "background") {
    if (this.disposed) return;
    const rank: Rank = priority === "shown" ? 0 : 1;
    const fresh: string[] = [];
    for (const iri of iris) {
      if (!isQueryableResource(iri) || iri.startsWith("<_:")) continue;
      if (this.options.known?.(iri)) continue;
      const cached = this.labels.get(iri);
      if (cached && cached.expires > this.now()) continue;
      const queued = this.queued.get(iri);
      if (queued !== undefined) {
        if (rank < queued) this.queued.set(iri, rank);
        continue;
      }
      if (this.lookups.has(iri)) continue;
      if (rank === 1 && this.asked + fresh.length >= (this.options.budget ?? DEFAULT_BUDGET)) continue;
      fresh.push(iri);
    }
    if (!fresh.length) return;
    this.asked += fresh.length;
    const backend = this.options.backend;
    if (!backend) {
      fresh.forEach((iri) => this.queued.set(iri, rank));
      return this.schedule();
    }
    const generation = this.generation;
    fresh.forEach((iri) => this.lookups.add(iri));
    backend
      .get(fresh.map((iri) => [this.options.namespace, "label", iri]))
      .catch(() => [] as never[])
      .then((rows) => {
        fresh.forEach((iri) => this.lookups.delete(iri));
        if (this.disposed || generation !== this.generation) return;
        let found = 0;
        const now = this.now();
        fresh.forEach((iri, index) => {
          const row = rows[index];
          const ttl = row?.entry.label === null ? NO_LABEL_TTL_MS : LABEL_TTL_MS;
          if (row && row.storedAt + ttl > now) {
            this.labels.set(iri, { label: row.entry.label, expires: row.storedAt + ttl });
            found++;
          } else this.queued.set(iri, rank);
        });
        if (found) this.notify();
        this.schedule();
      });
  }

  /** Labels still being looked up or asked for. */
  pending() {
    return this.queued.size + this.lookups.size + (this.running ? 1 : 0);
  }

  subscribe(listener: () => void) {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  }

  clear() {
    this.generation++;
    this.labels.clear();
    this.queued.clear();
    this.asked = 0;
    this.notify();
  }

  dispose() {
    this.disposed = true;
    this.controller.abort();
    this.listeners.clear();
    this.queued.clear();
  }

  private lookupProperties() {
    const preferred = this.options.properties ?? DEFAULT_LABEL_PROPERTIES;
    return this.options.lookupProperties ? [...new Set([...preferred, ...this.options.lookupProperties])] : preferred;
  }

  private notify() {
    this.version++;
    this.listeners.forEach((listener) => listener());
  }

  private schedule() {
    if (this.running || this.disposed) return;
    this.running = true;
    queueMicrotask(() => void this.drain());
  }

  private async drain() {
    try {
      while (!this.disposed && this.queued.size) {
        const batch = this.nextBatch();
        await this.load(batch);
      }
    } finally {
      this.running = false;
    }
  }

  private nextBatch() {
    const best = Math.min(...this.queued.values());
    const batch: string[] = [];
    for (const [iri, rank] of this.queued) {
      if (rank !== best) continue;
      batch.push(iri);
      if (batch.length >= this.batchSize) break;
    }
    batch.forEach((iri) => this.queued.delete(iri));
    return batch;
  }

  private async load(batch: string[]) {
    const generation = this.generation;
    let rows: Binding[];
    try {
      await this.options.foreground?.idle();
      const signal = AbortSignal.any([this.controller.signal, AbortSignal.timeout(TIMEOUT_MS)]);
      const query = valueLabelQuery(batch, this.lookupProperties(), this.options.scope);
      rows = (await this.options.execute(query, signal)).results?.bindings ?? [];
    } catch {
      // A failed batch leaves its values unlabelled for this visit; they show a readable form of the IRI.
      return;
    }
    if (this.disposed || generation !== this.generation) return;
    if (rows.length >= ROW_LIMIT && batch.length > 1) {
      // The reply may be cut off: ask again in halves.
      this.batchSize = Math.max(1, Math.floor(batch.length / 2));
      batch.forEach((iri) => this.queued.set(iri, 1));
      return;
    }
    const candidates = new Map<string, LabelCandidate[]>(batch.map((iri) => [iri, []]));
    for (const row of rows) {
      if (!isSparqlTerm(row.resource) || !isSparqlTerm(row.label) || row.label.type === "uri" || row.label.type === "bnode") continue;
      candidates.get(sparqlNodeId(row.resource))?.push({
        value: row.label.value,
        language: (row.label["xml:lang"] ?? "").toLowerCase(),
        property: row.labelProperty?.value ?? "",
      });
    }
    const now = this.now();
    const stored: Array<{ key: [string, string, string]; storedAt: number; entry: StoredLabel }> = [];
    candidates.forEach((list, iri) => {
      const label = chooseLabel(list, this.options.languages, this.options.properties) ?? null;
      this.labels.set(iri, { label, expires: now + (label === null ? NO_LABEL_TTL_MS : LABEL_TTL_MS) });
      stored.push({ key: [this.options.namespace, "label", iri], storedAt: now, entry: { label } });
    });
    void this.options.backend?.put(stored).catch(() => undefined);
    this.notify();
  }
}
